package com.smartlibrary.algorithms.string;import java.util.*;
public final class SuffixArray {private SuffixArray(){}public static int[] build(String s){int n=s.length();Integer[] a=new Integer[n];for(int i=0;i<n;i++)a[i]=i;Arrays.sort(a,(i,j)->s.substring(i).compareTo(s.substring(j)));return Arrays.stream(a).mapToInt(Integer::intValue).toArray();}public static int[] lcp(String s,int[] sa){int n=sa.length;int[] l=new int[n];for(int i=1;i<n;i++){int a=sa[i-1],b=sa[i],k=0;while(a+k<s.length()&&b+k<s.length()&&s.charAt(a+k)==s.charAt(b+k))k++;l[i]=k;}return l;}public static List<Integer> find(String s,int[] sa,String p){List<Integer> o=new ArrayList<>();for(int i:sa)if(s.startsWith(p,i))o.add(i);Collections.sort(o);return o;}}
